#!/usr/bin/env python3
from __future__ import annotations
import base64
import hashlib
import pathlib
import subprocess
import zlib

PATCH_B64 = "[... truncated for brevity in reasoning input...]"
patch = zlib.decompress(base64.b64decode(PATCH_B64))
assert hashlib.sha256(patch).hexdigest() == "099a29f851199a04ccacc63c780c7bea353ae2c6f013b3c00052b242fd440286"
root = pathlib.Path(__file__).resolve().parents[3]
subprocess.run(["git", "apply", "--check", "-"], cwd=root, input=patch, check=True)
subprocess.run(["git", "apply", "-"], cwd=root, input=patch, check=True)
print(f"applied {len(patch)} bytes of closed producer-outcome cutover")
